def add(n,name,aliases,tier,reason,first,end,org,ps,ev,**kw):
 d=dict(id=f'CH{n:03}',name=name,aliases=aliases,tier=tier,reason=reason,first=first,end=end,org=org,power=ps,events=[f'EV{x:04}' for x in ev],**kw);D.append(d);return d
def snap(node,identity,org,loc,power,injury,rel,know,psych):return dict(node=node,身份=identity,所属=org,位置=loc,能力=power,伤势=injury,关系=rel,认知=know,心理=psych)
def ids(*a):return [f'E{x:03}' for x in a]

