add(8,'祖母绿','研究院首席；林小姐（白狼称呼，非完整本名）','A','治疗、研究、政治和交易破局贯穿后段','L13272；EV0065','A：交易战后仍行动并被白狼等对抗；时间相关破局机制未定。','ORG004','PS027',[65,68,74,76,103,106,110,112,114,119,120,150,151],
stages=[['当代登场','研究院首席／院长；妖精拟态傀儡远程接触','A：L13303–13312；傀儡不是另一名妖精CH'],['研究治疗','与林昀合作修复本相和朝颜身体；协助龙胆伪装','A：EV0065、EV0076、EV0106、EV0112'],['末场','秘密收押褐鹈与交易对战金蛇','A/D：EV0150–EV0151；机构手段不等善恶定论']],
appearance=['傀儡拟态纯血妖精，具有机械部分（L13305）；绿宝石样瞳孔属于当场玩偶（L14255）。','代理身体、真实本体及不同装置分别登记，不合并外貌参数。','玩偶／办公睡眠表现有原文，但不补其本体永远穿睡衣。','完整本名仅“林小姐”称谓不足确认；本体身高体重年龄等未确认。'],
abilities='Ability Description：本相修复、备用身PS027，术式PS009/PS013与器械PS038；不能创造灵魂的说法保留D（EV0076）。\n\nDemonstrated Feats：修复朝颜、治疗翠雀、制造身份衣装与监控、对抗金蛇交易回撤（EV0065、EV0076、EV0106、EV0112、EV0151）。保留交易支出、记账和后续反制的具体表现；不能把“保留循环经历”直接定义世界时间循环或万能回档。',
changes=['EV0065：主动提出增值服务，治疗与交易性合作并行。','EV0076：本体和备用身体交接；不能从设备成功推复活任何死者。','EV0106：生成龙胆伪装及假证关联信息，人物位置和公众身份仍不自动改变。','EV0151：金蛇能力展示后改变应对，破局的具体底层分类仍未知。'],psych=['A：偷懒与研究成果并存，正文支持行为与发明能力（L13300–13304）。','D：对金绿猫眼的攻击性评价是本人意见，不是客观年龄、病理或婚史（L13315）。','C：整体政治目标不能仅由招揽或合作推定。'],patterns=['反复行为：以技术、治疗和资源提供方身份谈条件（EV0065、EV0076、EV0106）；不是无成本许愿提供者。','STAGE-BOUND：不同对手中的戏谑、敌意和商业谈判保留当场对象，不能概括对所有人同态。'],language='“后生”称呼有多场支持；“首席”是常用尊称；白狼的“林小姐”不扩展本名。',relations='CH001治疗／政治合作；CH005身体修复；CH015交易敌手；CH014旧紫钻称呼；CH034金绿猫眼同僚评价分层。',knowledge='持有研究及机构秘密不等所有研究员全知；给龙胆文件不等三个后辈知道其所有计划。',
snapshots=[snap('S01｜EV0065','首席，经傀儡接触','ORG004','LOC004远程代理','提供修复服务，尚非后续疗程完成','代理与本体损伤分开，未明F','与林谈合作','知自己提供的装备，其他动机F','A谈条件；评价D'),snap('S02｜EV0106','研究与伪装提供者','ORG004','LOC006','衣装伪装，不改身体','本体状态F','合作支持考核计划','伪证内容仅实际接触者知','A推进技术计划'),snap('S03｜EV0151','对战金蛇的首席','ORG004','末场外围／交易奇境','实际交易反制，原理不定','具体代价按交易，不补无限资源','与金蛇敌对','保留特定经历并查账，不等全知未来','A实验与应对；时间原理C/F')],unknown=['林小姐背后的完整本名、与林家血缘关系未知。','破局究竟属魔装、权能、术式或时间机制未知。','本体外貌与各代理体不能自动对应。'],evidence=ids(17,18,19,24,25,185,186,187,188,196,197,198,237,238,239,240,365,375),audit='回接C011/C018、M005/M009/M010/M015/M039。旧“循环”词仅作现象导航，机制仍F。'),

